<?php declare(strict_types=1);
$removePost=$lcPosted==='inventory-remove';$removeData=$removePost?$lcData:[];$removeLocations=[''=>$lcText('Lagerort auswählen')];$removeStock=[];foreach($archiveState['stock']as$stock){$free=max(0,(int)$stock['shelf']-(int)$stock['reserved']);$blocked=(int)$stock['blocked'];if($free+$blocked>0){$removeLocations[$stock['location_id']]=$lcText('{place} · {free} frei, {blocked} gesperrt',['place'=>$stock['location_name'],'free'=>(string)$free,'blocked'=>(string)$blocked]);$removeStock[$stock['location_id']]=['remove'=>$free,'discard'=>$blocked];}}
$removeLocation=$removeData['location']??(count($removeStock)===1?(string)array_key_first($removeStock):'');$removeKind=$removeData['kind']??(array_sum(array_column($removeStock,'remove'))>0?'remove':'discard');$removeLocations=\Kulturhus\Verein\Web\InventoryCatalogueForm::options($removeLocations,$removeLocation,$lcText('Ursprünglicher Lagerort nicht mehr verfügbar – bitte bewusst neu wählen'));
