<form method="post" action="<?= e($lcUrl('remove')) ?>" data-inventory-lifecycle-operation="remove" data-inventory-remove data-stock="<?= e(json_encode($removeStock,JSON_THROW_ON_ERROR)) ?>" data-remove-labels="<?= e(json_encode($removeLabels,JSON_THROW_ON_ERROR)) ?>"><?= $lcHeader('remove') ?><div class="iv-form-grid"><label><?= e($lcText('Von welchem Lagerort?')) ?> *<select class="form-control" name="data[location]" required><?php foreach($removeLocations as$id=>$caption): ?><option value="<?= e($id) ?>" <?= (string)$id===$removeLocation?'selected':'' ?>><?= e($caption) ?></option><?php endforeach ?></select></label><label><?= e($lcText('Welche Einheiten werden entfernt?')) ?> *<select class="form-control" name="data[kind]"><?php foreach(['remove'=>'Freier Lagerbestand','discard'=>'Gesperrte / defekte Einheiten']as$kind=>$caption): ?><option value="<?= e($kind) ?>" <?= $removeKind===$kind?'selected':'' ?>><?= e($lcText($caption)) ?></option><?php endforeach ?></select></label><label><?= e($lcText('Anzahl vollständiger Einheiten entfernen')) ?> *<input class="form-control" type="number" name="data[quantity]" value="<?= e($removeData['quantity']??'1') ?>" min="1" max="1000000" step="1" required></label></div><?php $lcReason('Warum wird diese Anzahl entfernt?',$removeData['reason']??''); ?><p data-remove-summary role="status"><?= e($lcText('Die verfügbaren Mengen stehen bei jedem Lagerort. Es wird nur die ausdrücklich bestätigte Anzahl entfernt.')) ?></p>
<?php if($item['purchase_units']):$selected=$removeData['purchase_unit_ids']??[]; ?><details class="iv-lifecycle-pieces" open><summary><?= e($lcText('Betroffene Stücke auswählen')) ?></summary><p><?= e($lcText('Nur die tatsächlich abgegangenen Stücke markieren. Für eine vollständige Entfernung aller Stücke dieses Gegenstands ist keine einzelne Auswahl nötig. Ursprüngliche Einzelpreise und Nachweise bleiben erhalten.')) ?></p><?php foreach($item['purchase_units']as$piece): ?><label class="check"><input type="checkbox" name="data[purchase_unit_ids][]" value="<?= e($piece['id']) ?>" <?= in_array($piece['id'],$selected,true)?'checked':'' ?>><span><?= e($lcText('Stück {number}',['number'=>(string)$piece['sequence']])) ?><?php if($piece['serial_number']!==''): ?> · <?= e($lcText('Seriennummer: {serial}',['serial'=>$piece['serial_number']])) ?><?php endif;if($canFinance): ?> · <?= $piece['unit_value_cents']===null?e($lcText('Preis unbekannt')):euro((int)$piece['unit_value_cents']) ?><?php endif ?></span></label><?php endforeach ?></details><?php endif ?>
<p><?= e($lcText('Reservierte und ausgeliehene Mengen können hier nicht entfernt werden. Eine Rechnung oder Zahlung wird nicht geändert.')) ?></p><button class="btn btn-solid theme-primary"><?= e($lcText('Diese Anzahl entfernen')) ?></button><?= hidden('inventory_lifecycle_complete','1') ?></form><script defer src="inventory-remove.js?v=2"></script>
<?php else: ?><p><?= e($lcText('Zurzeit keine freien oder gesperrten Einheiten zum Entfernen vorhanden. Offene Ausleihen zuerst im jeweiligen Vorgang klären.')) ?></p><?php endif ?>
